std::string chunk_receipt_relative_path_for_digest_or_throw(const NormalizedSyncPath& path,
                                                            const std::string& digest,
                                                            const SyncChunkRange& chunk,
                                                            const std::string& label) {
    const std::string staging_relative = remote_staging_relative_path_for_digest_or_throw(path, digest, label);
    return append_manifest_path_suffix_or_throw(
        NormalizedSyncPath{staging_relative + ".chunks/" + u64_string(chunk.offset) + "-" +
                           u64_string(chunk.length) + "-" + chunk.sha256 + ".receipt"},
        "",
        label).value;
}

bool same_chunk_range(const SyncChunkRange& left, const SyncChunkRange& right) {
    return left.offset == right.offset && left.length == right.length && left.sha256 == right.sha256;
}

bool manifest_contains_exact_chunk(const SyncManifestEntry& entry, const SyncChunkRange& chunk) {
    return std::any_of(entry.chunks.begin(), entry.chunks.end(), [&](const SyncChunkRange& candidate) {
        return same_chunk_range(candidate, chunk);
    });
}

bool apply_entry_stages_remote_file(const SyncLocalApplyPlanEntry& apply_entry) {
    return (apply_entry.source_action == SyncPlanAction::FetchRemoteFile &&
            apply_entry.local_action == SyncLocalApplyAction::StageRemoteFile) ||
           (apply_entry.source_action == SyncPlanAction::RecordConflict &&
            apply_entry.local_action == SyncLocalApplyAction::PreserveConflictCopy &&
            apply_entry.remote_entry_present &&
            apply_entry.remote_entry_kind == SyncManifestEntryKind::File);
}

SyncValidationResult validate_staged_remote_file_evidence(const SyncManifestEntry& remote_file_entry,
                                                           const SyncLocalApplyPlanEntry& apply_entry,
                                                           const std::string& label) {
    SyncValidationResult remote_result = validate_sync_manifest_entry(remote_file_entry);
    if (!remote_result.ok) return fail_result(label + " rejected remote entry: " + remote_result.reason);
    if (remote_file_entry.kind != SyncManifestEntryKind::File) return fail_result(label + " requires a remote file entry");
    if (!apply_entry_stages_remote_file(apply_entry)) {
        return fail_result(label + " requires an apply entry that stages a remote file");
    }
    if (apply_entry.path.value != remote_file_entry.path.value) return fail_result(label + " path does not match remote entry");

    const std::string expected_remote_digest = sync_manifest_entry_digest(remote_file_entry);
    const std::string expected_remote_version_digest = sync_manifest_entry_version_digest(remote_file_entry);
    if (!apply_entry.remote_entry_present || apply_entry.remote_entry_kind != SyncManifestEntryKind::File ||
        apply_entry.remote_size_bytes != remote_file_entry.size_bytes ||
        apply_entry.remote_content_sha256 != remote_file_entry.content_sha256 ||
        apply_entry.remote_entry_digest != expected_remote_digest ||
        apply_entry.remote_version_digest != expected_remote_version_digest) {
        return fail_result(label + " remote digest/content evidence does not match entry");
    }
    if (apply_entry.idempotency_key.empty() || !apply_entry.idempotency_key.starts_with("sync-local-apply:v1:")) {
        return fail_result(label + " requires a local apply idempotency key");
    }
    return ok_result();
}

