std::uint64_t prune_empty_parent_directories_up_to_root_or_throw(const fs::path& root_path,
                                                                 fs::path current_path,
                                                                 bool& pruned_any_out,
                                                                 const std::string& label) {
    pruned_any_out = false;
    std::uint64_t removed = 0;
    const fs::path root = root_path.lexically_normal();
    fs::path current = current_path.lexically_normal();
    while (path_is_strictly_inside(root, current)) {
        std::error_code status_ec;
        const fs::file_status status = fs::symlink_status(current, status_ec);
        if (status_ec) {
            if (status_ec == std::errc::no_such_file_or_directory) {
                current = current.parent_path();
                continue;
            }
            throw std::runtime_error(label + " could not inspect parent directory during pruning: " + status_ec.message());
        }
        if (!fs::exists(status)) {
            current = current.parent_path();
            continue;
        }
        if (fs::is_symlink(status)) throw std::runtime_error(label + " refuses to prune symlink parent directory");
        if (!fs::is_directory(status)) break;
        std::error_code empty_ec;
        const bool empty = fs::is_empty(current, empty_ec);
        if (empty_ec) throw std::runtime_error(label + " could not test parent directory emptiness: " + empty_ec.message());
        if (!empty) break;
        std::error_code remove_ec;
        const bool removed_one = fs::remove(current, remove_ec);
        if (remove_ec) throw std::runtime_error(label + " could not remove empty parent directory: " + remove_ec.message());
        if (removed_one) {
            ++removed;
            pruned_any_out = true;
            fsync_directory_if_supported_or_throw(current.parent_path(), label + " parent directory");
        }
        current = current.parent_path();
    }
    return removed;
}

