bool sync_checkpoint_apply_intent_routes_remote_file_bytes_to_staging(const std::string& source_action,
                                                                      const std::string& local_action) {
    return (source_action == "fetch_remote_file" && local_action == "stage_remote_file") ||
           (source_action == "record_conflict" && local_action == "preserve_conflict_copy");
}

bool sync_checkpoint_apply_intent_requires_terminal_conflict_file_apply(const std::string& source_action,
                                                                        const std::string& local_action) {
    return source_action == "record_conflict" && local_action == "preserve_conflict_copy";
}

SyncSessionCheckpointResumeViewOptions sync_terminal_apply_resume_view_safety_options(const SyncSessionCheckpointResumeTransferWorkorderDaemonLoopOptions& options) {
    SyncSessionCheckpointResumeViewOptions safety;
    safety.sqlite_path = options.sqlite_path;
    safety.session_id = options.session_id;
    safety.source_root_path = options.source_root_path;
    safety.destination_root_path = options.destination_root_path;
    safety.staging_root_path = options.staging_root_path;
    safety.expected_folder_id = options.expected_folder_id;
    safety.expected_source_device_id = options.expected_source_device_id;
    safety.expected_destination_device_id = options.expected_destination_device_id;
    safety.expected_peer_id = options.expected_peer_id;
    return safety;
}

SyncManifestEntry load_sync_session_manifest_entry_from_checkpoint_or_throw(sqlite3* db,
                                                                            const std::string& session_id,
                                                                            const std::string& role,
                                                                            const NormalizedSyncPath& path,
                                                                            const std::string& label) {
    if (!valid_sync_id(session_id)) throw std::runtime_error(label + " session_id is invalid");
    if (role != "source" && role != "destination_before" && role != "destination_after") {
        throw std::runtime_error(label + " role is invalid");
    }
    if (path.value.empty()) throw std::runtime_error(label + " path is required");
    SyncSqliteStmt entry_stmt = sqlite_prepare_or_throw(db,
        "SELECT m.folder_id, m.device_id, e.kind, e.size_bytes, e.content_sha256, "
        "e.conflict_set_id, e.entry_digest, e.version_digest, e.chunk_count, e.lineage_count "
        "FROM sync_session_manifest_entries e "
        "JOIN sync_session_manifests m ON m.session_id=e.session_id AND m.role=e.role "
        "WHERE e.session_id=? AND e.role=? AND e.path=?;",
        label + " manifest entry load prepare");
    sqlite_bind_text_or_throw(entry_stmt.stmt, 1, session_id, label + " manifest entry load session");
    sqlite_bind_text_or_throw(entry_stmt.stmt, 2, role, label + " manifest entry load role");
    sqlite_bind_text_or_throw(entry_stmt.stmt, 3, path.value, label + " manifest entry load path");
    const int entry_rc = sqlite3_step(entry_stmt.stmt);
    if (entry_rc != SQLITE_ROW) throw std::runtime_error(label + " manifest entry row not found");

    // Cardinality evidence is observed before any attacker-controlled text is
    // copied into C++ ownership. Every text copy also has its semantic maximum
    // enforced at the SQLite boundary.
    const std::uint64_t expected_chunks = sqlite_column_u64_or_throw(
        entry_stmt.stmt, 8, label + " manifest entry chunk count");
    const std::uint64_t expected_lineage = sqlite_column_u64_or_throw(
        entry_stmt.stmt, 9, label + " manifest entry lineage count");
    const std::string folder_id = sqlite_column_text_or_throw(
        entry_stmt.stmt, 0, kSyncManifestIdMaxBytes,
        label + " manifest entry folder id");
    const std::string device_id = sqlite_column_text_or_throw(
        entry_stmt.stmt, 1, kSyncManifestIdMaxBytes,
        label + " manifest entry device id");
    const std::string kind_text = sqlite_column_text_or_throw(
        entry_stmt.stmt, 2, kSyncManifestKindTextMaxBytes,
        label + " manifest entry kind");
    SyncManifestEntryKind kind = SyncManifestEntryKind::File;
    if (kind_text == "file") kind = SyncManifestEntryKind::File;
    else if (kind_text == "tombstone") kind = SyncManifestEntryKind::Tombstone;
    else throw std::runtime_error(label + " manifest entry kind is unsupported");
    const std::uint64_t size_bytes = sqlite_column_u64_or_throw(
        entry_stmt.stmt, 3, label + " manifest entry size");
    const std::string content_sha256 = sqlite_column_text_or_throw(
        entry_stmt.stmt, 4, kSyncManifestSha256TextBytes,
        label + " manifest entry content sha");
    const std::string conflict_set_id = sqlite_column_text_or_throw(
        entry_stmt.stmt, 5, kSyncManifestIdMaxBytes,
        label + " manifest entry conflict set id");
    const std::string stored_entry_digest = sqlite_column_text_or_throw(
        entry_stmt.stmt, 6, kSyncManifestSha256TextBytes,
        label + " stored entry digest");
    const std::string stored_version_digest = sqlite_column_text_or_throw(
        entry_stmt.stmt, 7, kSyncManifestSha256TextBytes,
        label + " stored version digest");
    const int duplicate_entry_rc = sqlite3_step(entry_stmt.stmt);
    if (duplicate_entry_rc != SQLITE_DONE) throw std::runtime_error(label + " manifest entry row is not unique");

    SyncManifestEntryStreamDecoder decoder;
    const SyncValidationResult begin_result = decoder.begin({
        folder_id,
        device_id,
        path.value,
        kind,
        size_bytes,
        content_sha256,
        conflict_set_id,
        expected_chunks,
        expected_lineage,
    });
    if (!begin_result.ok) {
        throw std::runtime_error(
            label + " manifest entry validation failed before row decode: " +
            begin_result.reason);
    }

    SyncSqliteStmt chunk_stmt = sqlite_prepare_or_throw(db,
        "SELECT chunk_offset, chunk_length, chunk_sha256 "
        "FROM sync_session_manifest_chunks "
        "WHERE session_id=? AND role=? AND path=? ORDER BY chunk_index;",
        label + " manifest chunk load prepare");
    sqlite_bind_text_or_throw(chunk_stmt.stmt, 1, session_id, label + " manifest chunk load session");
    sqlite_bind_text_or_throw(chunk_stmt.stmt, 2, role, label + " manifest chunk load role");
    sqlite_bind_text_or_throw(chunk_stmt.stmt, 3, path.value, label + " manifest chunk load path");
    while (true) {
        const int rc = sqlite3_step(chunk_stmt.stmt);
        if (rc == SQLITE_DONE) break;
        if (rc != SQLITE_ROW) throw std::runtime_error(label + " manifest chunk load failed");
        const std::uint64_t offset = sqlite_column_u64_or_throw(
            chunk_stmt.stmt, 0, label + " manifest chunk offset");
        const std::uint64_t length = sqlite_column_u64_or_throw(
            chunk_stmt.stmt, 1, label + " manifest chunk length");
        const std::string sha256 = sqlite_column_text_or_throw(
            chunk_stmt.stmt, 2, kSyncManifestSha256TextBytes,
            label + " manifest chunk sha");
        const SyncValidationResult append_result =
            decoder.append_chunk(offset, length, sha256);
        if (!append_result.ok) {
            throw std::runtime_error(
                label + " manifest entry validation failed during chunk decode: " +
                append_result.reason);
        }
    }

    SyncSqliteStmt lineage_stmt = sqlite_prepare_or_throw(db,
        "SELECT lineage_device_id, lineage_counter "
        "FROM sync_session_manifest_lineage "
        "WHERE session_id=? AND role=? AND path=? ORDER BY lineage_index;",
        label + " manifest lineage load prepare");
    sqlite_bind_text_or_throw(lineage_stmt.stmt, 1, session_id, label + " manifest lineage load session");
    sqlite_bind_text_or_throw(lineage_stmt.stmt, 2, role, label + " manifest lineage load role");
    sqlite_bind_text_or_throw(lineage_stmt.stmt, 3, path.value, label + " manifest lineage load path");
    while (true) {
        const int rc = sqlite3_step(lineage_stmt.stmt);
        if (rc == SQLITE_DONE) break;
        if (rc != SQLITE_ROW) throw std::runtime_error(label + " manifest lineage load failed");
        const std::string lineage_device_id = sqlite_column_text_or_throw(
            lineage_stmt.stmt, 0, kSyncManifestIdMaxBytes,
            label + " manifest lineage device");
        const std::uint64_t lineage_counter = sqlite_column_u64_or_throw(
            lineage_stmt.stmt, 1, label + " manifest lineage counter");
        const SyncValidationResult append_result =
            decoder.append_lineage(lineage_device_id, lineage_counter);
        if (!append_result.ok) {
            throw std::runtime_error(
                label + " manifest entry validation failed during lineage decode: " +
                append_result.reason);
        }
    }

    SyncManifestEntry entry;
    const SyncValidationResult finish_result = decoder.finish(entry);
    if (!finish_result.ok) {
        throw std::runtime_error(
            label + " manifest entry validation failed at row commit: " +
            finish_result.reason);
    }
    if (sync_manifest_entry_digest(entry) != stored_entry_digest ||
        sync_manifest_entry_version_digest(entry) != stored_version_digest) {
        throw std::runtime_error(label + " manifest entry digest evidence does not round-trip from checkpoint rows");
    }
    return entry;
}

std::uint64_t count_sync_session_checkpoint_file_transfer_intents_or_throw(const SyncSessionCheckpointResumeTransferWorkorderDaemonLoopOptions& options) {
    const fs::path sqlite_path = absolute_lexically_normal_path_or_throw(options.sqlite_path,
                                                                         "sync session checkpoint file transfer intent count sqlite_path");
    require_checkpoint_sqlite_read_path_safe_or_throw(sqlite_path, sync_terminal_apply_resume_view_safety_options(options));
    SyncSqliteDb handle;
    int flags = SQLITE_OPEN_READONLY | SQLITE_OPEN_FULLMUTEX;
#ifdef SQLITE_OPEN_NOFOLLOW
    flags |= SQLITE_OPEN_NOFOLLOW;
#endif
    const int open_rc = ::anonsync::persistence::open_verified_sqlite_database(sqlite_path.string().c_str(), handle.db.out(), flags, nullptr);
    if (open_rc != SQLITE_OK) throw std::runtime_error(sqlite_error_message(handle.db, "sync session checkpoint file transfer intent count could not open sqlite database"));
    sqlite_exec_or_throw(handle.db, "PRAGMA query_only=ON;", "sync session checkpoint file transfer intent count query_only");
    if (!sqlite_table_exists_or_throw(handle.db,
                                      "sync_session_apply_intents",
                                      "sync session checkpoint file transfer intent count apply intents")) {
        return 0;
    }
    if (!sqlite_table_exists_or_throw(handle.db,
                                      "sync_session_manifest_entries",
                                      "sync session checkpoint file transfer intent count manifest entries")) {
        return 0;
    }
    return sqlite_count_for_session_or_throw(handle.db,
        "SELECT COUNT(*) FROM sync_session_apply_intents a "
        "JOIN sync_session_manifest_entries e ON e.session_id=a.session_id AND e.role='source' AND e.path=a.path "
        "WHERE a.session_id=? AND e.kind='file' AND "
        "((a.source_action='fetch_remote_file' AND a.local_action='stage_remote_file') OR "
        " (a.source_action='record_conflict' AND a.local_action='preserve_conflict_copy')) AND "
        "NOT (a.source_action='record_conflict' AND a.local_action='preserve_conflict_copy' AND EXISTS ("
        "SELECT 1 FROM sync_session_terminal_apply_workorders tw "
        "WHERE tw.session_id=a.session_id AND tw.path=a.path AND tw.source_action='record_conflict' "
        "AND tw.local_action='preserve_conflict_copy' AND tw.work_state='completed'));",
        options.session_id,
        "sync session checkpoint file transfer intent count");
}

