                sqlite_bind_u64_or_throw(timed_stmt.stmt, 3, options.scheduler_now_epoch, "sync session checkpoint operator status expired claimed now");
                sqlite_bind_u64_or_throw(timed_stmt.stmt, 4, options.scheduler_now_epoch, "sync session checkpoint operator status retryable expired now 1");
                sqlite_bind_u64_or_throw(timed_stmt.stmt, 5, options.scheduler_now_epoch, "sync session checkpoint operator status retryable expired now 2");
                sqlite_bind_u64_or_throw(timed_stmt.stmt, 6, options.scheduler_now_epoch, "sync session checkpoint operator status cooling expired now 1");
                sqlite_bind_u64_or_throw(timed_stmt.stmt, 7, options.scheduler_now_epoch, "sync session checkpoint operator status cooling expired now 2");
                sqlite_bind_text_or_throw(timed_stmt.stmt, 8, options.session_id, "sync session checkpoint operator status timed workorder metrics session");
                const int timed_rc = sqlite3_step(timed_stmt.stmt);
                if (timed_rc != SQLITE_ROW) throw std::runtime_error("sync session checkpoint operator status timed workorder metrics returned no row");
                out.live_claimed_workorder_rows = sqlite_column_u64_or_throw(timed_stmt.stmt, 0, "sync session checkpoint operator status live claimed workorders");
                out.expired_claimed_workorder_rows = sqlite_column_u64_or_throw(timed_stmt.stmt, 1, "sync session checkpoint operator status expired claimed workorders");
                out.retryable_expired_workorder_rows = sqlite_column_u64_or_throw(timed_stmt.stmt, 2, "sync session checkpoint operator status retryable expired workorders");
                out.cooling_down_expired_workorder_rows = sqlite_column_u64_or_throw(timed_stmt.stmt, 3, "sync session checkpoint operator status cooling expired workorders");
