            out.conflict_terminal_apply_workorder_rows = sqlite_column_u64_or_throw(terminal_stmt.stmt, 7, "sync session checkpoint operator status conflict terminal apply rows");
            out.conflict_terminal_apply_completed_rows = sqlite_column_u64_or_throw(terminal_stmt.stmt, 8, "sync session checkpoint operator status completed conflict terminal apply rows");
            out.conflict_terminal_apply_targets_removed = sqlite_column_u64_or_throw(terminal_stmt.stmt, 9, "sync session checkpoint operator status conflict terminal apply removed targets");
            if (has_manifest_entry_table) {
                SyncSqliteStmt conflict_file_stmt = sqlite_prepare_or_throw(handle.db,
                    "SELECT "
                    "COALESCE(SUM(CASE WHEN e.kind='file' THEN 1 ELSE 0 END),0), "
                    "COALESCE(SUM(CASE WHEN e.kind='file' AND t.work_state='completed' THEN 1 ELSE 0 END),0), "
                    "COALESCE(SUM(CASE WHEN e.kind='file' AND t.work_state='completed' AND t.target_removed=0 AND t.target_already_absent=0 THEN 1 ELSE 0 END),0) "
                    "FROM sync_session_terminal_apply_workorders t "
                    "JOIN sync_session_manifest_entries e ON e.session_id=t.session_id AND e.role='source' AND e.path=t.path "
                    "WHERE t.session_id=? AND t.source_action='record_conflict';",
                    "sync session checkpoint operator status conflict file terminal metrics prepare");
                sqlite_bind_text_or_throw(conflict_file_stmt.stmt, 1, options.session_id, "sync session checkpoint operator status conflict file terminal metrics session");
                const int conflict_file_rc = sqlite3_step(conflict_file_stmt.stmt);
                if (conflict_file_rc != SQLITE_ROW) throw std::runtime_error("sync session checkpoint operator status conflict file terminal metrics returned no row");
                out.conflict_file_terminal_apply_workorder_rows = sqlite_column_u64_or_throw(conflict_file_stmt.stmt, 0, "sync session checkpoint operator status conflict file terminal apply rows");
                out.conflict_file_terminal_apply_completed_rows = sqlite_column_u64_or_throw(conflict_file_stmt.stmt, 1, "sync session checkpoint operator status completed conflict file terminal apply rows");
                out.conflict_file_terminal_apply_targets_materialized = sqlite_column_u64_or_throw(conflict_file_stmt.stmt, 2, "sync session checkpoint operator status conflict file terminal apply materialized targets");
            }
