                out.latest_daemon_worker_lease_id = sqlite_column_text_or_throw(latest.stmt, 2, "sync session checkpoint operator status latest daemon worker lease id");
                out.latest_daemon_worker_lease_epoch = sqlite_column_u64_or_throw(latest.stmt, 3, "sync session checkpoint operator status latest daemon worker lease epoch");
                out.latest_daemon_lease_started_at_epoch = sqlite_column_u64_or_throw(latest.stmt, 4, "sync session checkpoint operator status latest daemon lease start");
                out.latest_daemon_lease_expires_at_epoch = sqlite_column_u64_or_throw(latest.stmt, 5, "sync session checkpoint operator status latest daemon lease expiry");
                out.latest_daemon_lease_reason = sqlite_column_text_or_throw(latest.stmt, 6, "sync session checkpoint operator status latest daemon lease reason");
